// moonproof hash router (single router for the static site; no build step).
// Routes look like  #/comparar/tecnico?site=connecting-ridge . The selected site is global
// state carried in the URL (?site=), so it survives page changes, reloads and shared links.
// Pure helpers are exported for node --test; startRouter() wires the DOM.
// Source of truth: this .ts file. router.js is generated by `npm --prefix web run build:ts`.
/** Board (onboard cockpit) sections: route slug -> cockpit tab id. "entrada" was renamed "parametros". */
export const BORDO_SECTIONS = {
    "": "visao", "visao-geral": "visao", parametros: "entrada", geometria: "geometria", horizonte: "horizonte",
    janelas: "janelas", navegacao: "navegacao", energia: "energia", vida: "vida", replanejar: "replan", visual: "visual",
    sensibilidade: "sens", registro: "historico", lancamentos: "lanc", status: "status",
};
export const BORDO_SLUG = Object.fromEntries(Object.entries(BORDO_SECTIONS).filter(([k]) => k).map(([k, v]) => [v, k]));
/** Old links that must keep working (hash fragments used before v3). */
export const LEGACY = {
    "#explore": "/explorar", "#compare": "/comparar", "#recover": "/bordo/replanejar", "#science": "/bordo/sensibilidade",
    "#evidence": "/evidencias", "#lab": "/terreno", "#main": "/",
    // old cockpit tab anchors (#energia, #replan …) when opened on the shell
    ...Object.fromEntries(Object.entries(BORDO_SLUG).map(([tab, slug]) => ["#" + tab, "/bordo/" + slug])),
};
/** "#/a/b?site=x&k=1" -> { path: "/a/b", parts: ["a","b"], query: {site:"x",k:"1"} } */
export function parseHash(hash) {
    const raw = (hash || "").replace(/^#/, "");
    const [p, q = ""] = raw.split("?");
    let path = "/" + (p || "").replace(/^\/+/, "").replace(/\/+$/, "");
    path = path.replace(/\/{2,}/g, "/");
    const query = {};
    for (const [k, v] of new URLSearchParams(q))
        query[k] = v;
    return { path, parts: path.split("/").filter(Boolean), query };
}
/** Build "#/path?k=v" keeping only defined, non-empty values; keys sorted for stable links. */
export function buildHash(path, query = {}) {
    const clean = "/" + String(path || "/").replace(/^\/+/, "").replace(/\/+$/, "");
    const qs = new URLSearchParams(Object.entries(query).filter(([, v]) => v !== undefined && v !== null && v !== "").sort(([a], [b]) => a.localeCompare(b)));
    const s = qs.toString();
    return "#" + clean + (s ? "?" + s : "");
}
/** Legacy fragment -> new hash, or null when the hash is already a v3 route. */
export function legacyRedirect(hash) {
    if (!hash || hash.startsWith("#/"))
        return null;
    const target = LEGACY[hash.split("?")[0]];
    return target ? buildHash(target) : null;
}
/** Resolve a path against a route table [{path:"/comparar/tecnico", ...}] — longest prefix wins, "/" exact. */
export function resolveRoute(routes, path) {
    const exact = routes.find(r => r.path === path);
    if (exact)
        return { route: exact, rest: [] };
    const prefix = routes.filter(r => r.prefix && r.path !== "/" && (path === r.path || path.startsWith(r.path + "/")))
        .sort((a, b) => b.path.length - a.path.length)[0];
    if (prefix)
        return { route: prefix, rest: path.slice(prefix.path.length).split("/").filter(Boolean) };
    return { route: routes.find(r => r.notFound) || null, rest: [] };
}
/** URL of the cockpit page for a board route (keeps ?site=). */
export function bordoURL(base, parts, query) {
    const slug = parts[1] && BORDO_SECTIONS[parts[1]] ? parts[1] : "";
    return base + buildHash("/bordo" + (slug ? "/" + slug : ""), { site: query.site });
}
// The onboard cockpit is a classic-script page; it uses the same router helpers through this global.
if (typeof window !== "undefined") {
    window.MoonproofRouter = { parseHash, buildHash, legacyRedirect, BORDO_SECTIONS, BORDO_SLUG, saveLastRoute: (h) => saveLastRoute(h) };
}
const LAST_KEY = "moonproof:last-route";
export function saveLastRoute(hash) { try {
    localStorage.setItem(LAST_KEY, hash);
}
catch { /* storage unavailable */ } }
export function loadLastRoute() { try {
    return localStorage.getItem(LAST_KEY);
}
catch {
    return null;
} }
/**
 * Start the router. routes: [{path, title, prefix?, notFound?, render(ctx) -> Promise|void, external?(ctx)}]
 * ctx = { path, parts, rest, query, site, go(path, query), setSite(id) }.
 * On every route change: renders into `outlet`, updates <title>, moves focus to [data-route-title], stores last route.
 */
export function startRouter({ routes, outlet, appName = "moonproof", onAfter }) {
    let current = null;
    const go = (path, query = {}) => { location.hash = buildHash(path, query); };
    async function handle() {
        const legacy = legacyRedirect(location.hash);
        if (legacy) {
            location.replace(legacy);
            return;
        }
        const { path, parts, query } = parseHash(location.hash || "#/");
        const { route, rest } = resolveRoute(routes, path);
        if (!route)
            return;
        const ctx = {
            path, parts, rest, query, site: query.site || null,
            go: (p, q) => go(p, { site: query.site, ...q }),
            setSite: (id) => { const q = { ...query, site: id }; history.replaceState(null, "", buildHash(path, q)); return q; },
        };
        if (route.external) {
            route.external(ctx);
            return;
        }
        current = path;
        outlet.replaceChildren();
        outlet.setAttribute("aria-busy", "true");
        try {
            await route.render?.(outlet, ctx);
        }
        finally {
            outlet.removeAttribute("aria-busy");
        }
        if (current !== path)
            return; // a newer navigation happened while rendering
        document.title = (typeof route.title === "function" ? route.title(ctx) : route.title) + " · " + appName;
        const h1 = outlet.querySelector("[data-route-title]") || outlet.querySelector("h1");
        if (h1) {
            h1.setAttribute("tabindex", "-1");
            h1.focus({ preventScroll: false });
        }
        if (path !== "/")
            saveLastRoute(location.hash);
        onAfter?.(ctx, route);
    }
    addEventListener("hashchange", handle);
    if (!location.hash)
        history.replaceState(null, "", "#/");
    handle();
    return { go, refresh: handle };
}
